import { useState } from "react";
function MyForm() {
    const [name, setName] = React.useState('');
  return (
    <form>
      <label>
        Name:
        <input type="text" onChange={e => setName(e.target.value)} />
      </label>
      <button type="submit">Submit</button>
    </form>
  );
}
export default MyForm;
